import{_ as l,a0 as i,w as u,s as r,ao as o,I as t,x as s,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"我喜歡 Vue 的 10 個方面 | LCTT x X-CMD","titleTemplate":false,"description":"我喜歡 Vue 的 10 個方面 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我喜歡 Vue 的 10 個方面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我喜歡 Vue 的 10 個方面 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180131 10 things I love about Vue","title":"我喜歡 Vue 的 10 個方面","tag":"201803","desc":""},"relativePath":"201803/20180131 10 things I love about Vue.md","filePath":"[post].md"}'),d={name:"201803/20180131 10 things I love about Vue.md"};function h(c,a,m,g,b,k){const n=i("Link");return u(),r("div",null,[a[15]||(a[15]=o(`<h1 id="我喜歡-vue-的-10-個方面" tabindex="-1">我喜歡 Vue 的 10 個方面 <a class="header-anchor" href="#我喜歡-vue-的-10-個方面" aria-label="Permalink to “我喜歡 Vue 的 10 個方面”">​</a></h1><p><img src="https://cdn-images-1.medium.com/max/1600/1*X4ipeKVYzmY2M3UPYgUYuA.png" alt=""></p><p>我喜歡 Vue。當我在 2016 年第一次接觸它時，也許那時我已經對 JavaScript 框架感到疲勞了，因為我已經具有Backbone、Angular、React 等框架的經驗，沒有太多的熱情去嘗試一個新的框架。直到我在 Hacker News 上讀到一份評論，其描述 Vue 是類似於“新 jQuery” 的 JavaScript 框架，從而激發了我的好奇心。在那之前，我已經相當滿意 React 這個框架，它是一個很好的框架，建立於可靠的設計原則之上，圍繞着視圖模板、虛擬 DOM 和狀態響應等技術。而 Vue 也提供了這些重要的內容。</p><p>在這篇文章中，我旨在解釋為什麼 Vue 適合我，為什麼在上文中那些我嘗試過的框架中選擇它。也許你將同意我的一些觀點，但至少我希望能夠給大家使用 Vue 開發現代 JavaScript 應用一些靈感。</p><h3 id="_1、-極少的模板語法" tabindex="-1">1、 極少的模板語法 <a class="header-anchor" href="#_1、-極少的模板語法" aria-label="Permalink to “1、 極少的模板語法”">​</a></h3><p>Vue 默認提供的視圖模板語法是極小的、簡潔的和可擴展的。像其他 Vue 部分一樣，可以很簡單的使用類似 JSX 一樣語法，而不使用標準的模板語法（甚至有官方文檔説明了如何做），但是我覺得沒必要這麼做。JSX 有好的方面，也有一些有依據的批評，如混淆了 JavaScript 和 HTML，使得很容易導致在模板中出現複雜的代碼，而本來應該分開寫在不同的地方的。</p><p>Vue 沒有使用標準的 HTML 來編寫視圖模板，而是使用極少的模板語法來處理簡單的事情，如基於視圖數據迭代創建元素。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;template&gt;</span></span>
<span class="line"><span>  &lt;div id=&quot;app&quot;&gt;</span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      &lt;li v-for=&#39;number in numbers&#39; :key=&#39;number&#39;&gt;{{ number }}&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span>    &lt;form @submit.prevent=&#39;addNumber&#39;&gt;</span></span>
<span class="line"><span>      &lt;input type=&#39;text&#39; v-model=&#39;newNumber&#39;&gt;</span></span>
<span class="line"><span>      &lt;button type=&#39;submit&#39;&gt;Add another number&lt;/button&gt;</span></span>
<span class="line"><span>    &lt;/form&gt;</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>&lt;/template&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;script&gt;</span></span>
<span class="line"><span>export default {</span></span>
<span class="line"><span>  name: &#39;app&#39;,</span></span>
<span class="line"><span>  methods: {</span></span>
<span class="line"><span>    addNumber() {</span></span>
<span class="line"><span>      const num = +this.newNumber;</span></span>
<span class="line"><span>      if (typeof num === &#39;number&#39; &amp;&amp; !isNaN(num)) {</span></span>
<span class="line"><span>        this.numbers.push(num);</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  data() {</span></span>
<span class="line"><span>    return {</span></span>
<span class="line"><span>      newNumber: null,</span></span>
<span class="line"><span>      numbers: [1, 23, 52, 46]</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/script&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;style lang=&quot;scss&quot;&gt;</span></span>
<span class="line"><span>ul {</span></span>
<span class="line"><span>  padding: 0;</span></span>
<span class="line"><span>  li {</span></span>
<span class="line"><span>    list-style-type: none;</span></span>
<span class="line"><span>    color: blue;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/style&gt;</span></span></code></pre></div><p>我也喜歡 Vue 提供的簡短綁定語法，<code>:</code> 用於在模板中綁定數據變量，<code>@</code> 用於綁定事件。這是一個細節，但寫起來很爽而且能夠讓你的組件代碼簡潔。</p><h3 id="_2、-單文件組件" tabindex="-1">2、 單文件組件 <a class="header-anchor" href="#_2、-單文件組件" aria-label="Permalink to “2、 單文件組件”">​</a></h3><p>大多數人使用 Vue，都使用“單文件組件”。本質上就是一個 .vue 文件對應一個組件，其中包含三部分（CSS、HTML和JavaScript）。</p><p>這種技術結合是對的。它讓人很容易在一個單獨的地方瞭解每個組件，同時也非常好的鼓勵了大家保持每個組件代碼的簡短。如果你的組件中 JavaScript、CSS 和 HTML 代碼佔了很多行，那麼就到了進一步模組化的時刻了。</p><p>在使用 Vue 組件中的 <code>&lt;style&gt;</code> 標籤時，我們可以添加 <code>scoped</code> 屬性。這會讓整個樣式完全的封裝到當前組件，意思是在組件中如果我們寫了 <code>.name</code> 的 css 選擇器，它不會把樣式應用到其他組件中。我非常喜歡這種方式來應用樣式而不是像其他主要框架流行在 JS 中編寫 CSS 的方式。</p><p>關於單文件組件另一個好處是 .vue 文件實際上是一個有效的 HTML 5 文件。<code>&lt;template&gt;</code>、 <code>&lt;script&gt;</code>、 <code>&lt;style&gt;</code> 都是 w3c 官方規範的標籤。這就表示很多如 linters （LCTT 譯註：一種代碼檢查工具插件）這樣我們用於開發過程中的工具能夠開箱即用或者添加一些適配後使用。</p><h3 id="_3、-vue-新的-jquery" tabindex="-1">3、 Vue “新的 jQuery” <a class="header-anchor" href="#_3、-vue-新的-jquery" aria-label="Permalink to “3、 Vue “新的 jQuery””">​</a></h3><p>事實上，這兩個庫不相似而且用於做不同的事。讓我提供給你一個很精闢的類比（我實際上非常喜歡描述 Vue 和 jQuery 之間的關係）：披頭士樂隊和齊柏林飛船樂隊（LCTT 譯註：兩個都是英國著名的樂隊）。披頭士樂隊不需要介紹，他們是 20 世紀 60 年代最大的和最有影響力的樂隊。但很難説披頭士樂隊是 20 世紀 70 年代最大的樂隊，因為有時這個榮耀屬於是齊柏林飛船樂隊。你可以説兩個樂隊之間有着微妙的音樂聯繫或者説他們的音樂是明顯不同的，但兩者一些先前的藝術和影響力是不可否認的。也許 21 世紀初 JavaScript 的世界就像 20 世紀 70 年代的音樂世界一樣，隨着 Vue 獲得更多關注使用，只會吸引更多粉絲。</p><p>一些使 jQuery 牛逼的哲學理念在 Vue 中也有呈現：非常容易的學習曲線但卻具有基於現代 web 標準構建牛逼 web 應用所有你需要的功能。Vue 的核心本質上就是在 JavaScript 對象上包裝了一層。</p><h3 id="_4、-極易擴展" tabindex="-1">4、 極易擴展 <a class="header-anchor" href="#_4、-極易擴展" aria-label="Permalink to “4、 極易擴展”">​</a></h3><p>正如前述，Vue 默認使用標準的 HTML、JS 和 CSS 構建組件，但可以很容易插入其他技術。如果我們想使用pug（LCTT譯註：一款功能豐富的模板引擎，專門為 Node.js 平台開發）替換 HTML 或者使用 Typescript（LCTT譯註：一種由微軟開發的編程語言，是 JavaScript 的一個超集）替換 js 或者 Sass （LCTT 譯註：一種 CSS 擴展語言）替換 CSS，只需要安裝相關的 node 模組和在我們的單文件組件中添加一個屬性到相關的標籤即可。你甚至可以在一個項目中混合搭配使用 —— 如一些組件使用 HTML 其他使用 pug ——然而我不太確定這麼做是最好的做法。</p><h3 id="_5、-虛擬-dom" tabindex="-1">5、 虛擬 DOM <a class="header-anchor" href="#_5、-虛擬-dom" aria-label="Permalink to “5、 虛擬 DOM”">​</a></h3><p>虛擬 DOM 是很好的技術，被用於現如今很多框架。其意味着這些框架能夠做到根據我們狀態的改變來高效的完成 DOM 更新，減少重新渲染，從而優化我們應用的性能。現如今每個框架都有虛擬 DOM 技術，所以雖然它不是什麼獨特的東西，但它仍然很出色。</p><h3 id="_6、-vuex-很棒" tabindex="-1">6、 Vuex 很棒 <a class="header-anchor" href="#_6、-vuex-很棒" aria-label="Permalink to “6、 Vuex 很棒”">​</a></h3><p>對於大多數應用，管理狀態成為一個棘手的問題，單獨使用一個視圖庫不能解決這個問題。Vue 使用 Vuex 庫來解決這個問題。Vuex 很容易構建而且和 Vue 集成的很好。熟悉 redux（另一個管理狀態的庫）的人學習 Vuex 會覺得輕車熟路，但是我發現 Vue 和 Vuex 集成起來更加簡潔。最新 JavaScript 草案中（LCTT 譯註：應該是指 ES7）提供了對象展開運算符（LCTT 譯註：符號為 <code>...</code>），允許我們在狀態或函數中進行合併，以操縱從 Vuex 到需要它的 Vue 組件中的狀態。</p><h3 id="_7、-vue-的命令列界面-cli" tabindex="-1">7、 Vue 的命令列界面（CLI） <a class="header-anchor" href="#_7、-vue-的命令列界面-cli" aria-label="Permalink to “7、 Vue 的命令列界面（CLI）”">​</a></h3><p>Vue 提供的命令列界面非常不錯，很容易用 Vue 搭建一個基於 Webpack（LCTT 譯註：一個前端資源加載/打包工具）的項目。單文件組件支持、babel（LCTT 譯註：js 語法轉換器）、linting（LCTT譯註：代碼檢查工具）、測試工具支持，以及合理的項目結構，都可以在終端中一行命令創建。</p><p>然而有一個命令，我在 CLI 中沒有找到，那就是 <code>vue build</code>。</p><blockquote><p>如：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;template&gt;&lt;h1&gt;Hello World!&lt;/h1&gt;&lt;/template&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hello.vue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hello.vue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div></blockquote><p><code>vue build</code> 命令構建和運行組件並在瀏覽器中測試看起來非常簡單。很不幸這個命令後來在 Vue 中刪除了，現在推薦使用 Poi。Poi 本質上是在 Webpack 工具上封裝了一層，但我不認我它像推特上説的那樣簡單。</p><h3 id="_8、-重新渲染優化" tabindex="-1">8、 重新渲染優化 <a class="header-anchor" href="#_8、-重新渲染優化" aria-label="Permalink to “8、 重新渲染優化”">​</a></h3><p>使用 Vue，你不必手動聲明 DOM 的哪部分應該被重新渲染。我從來都不喜歡操縱 React 組件的渲染，像在<code>shouldComponentUpdate</code> 方法中停止整個 DOM 樹重新渲染這種。Vue 在這方面非常巧妙。</p><h3 id="_9、-容易獲得幫助" tabindex="-1">9、 容易獲得幫助 <a class="header-anchor" href="#_9、-容易獲得幫助" aria-label="Permalink to “9、 容易獲得幫助”">​</a></h3><p>Vue 已經達到了使用這個框架來構建各種各樣的應用的一種羣聚效應。開發文檔非常完善。如果你需要進一步的幫助，有多種渠道可用，每個渠道都有很多活躍開發者：stackoverflow、discord、twitter 等。相對於其他用户量少的框架，這就應該給你更多的信心來使用Vue構建應用。</p><h3 id="_10、-多機構維護" tabindex="-1">10、 多機構維護 <a class="header-anchor" href="#_10、-多機構維護" aria-label="Permalink to “10、 多機構維護”">​</a></h3><p>我認為，一個開源庫，在發展方向方面的投票權利沒有被單一機構操縱過多，是一個好事。就如同 React 的許可證問題（現已解決），Vue 就不可能涉及到。</p><p>總之，作為你接下來要開發的任何 JavaScript 項目，我認為 Vue 都是一個極好的選擇。Vue 可用的生態圈比我Blog中涉及到的其他庫都要大。如果想要更全面的產品，你可以關注 Nuxt.js。如果你需要一些可重複使用的樣式組件你可以關注類似 Vuetify 的庫。</p><p>Vue 是 2017 年增長最快的庫之一，我預測在 2018 年增長速度不會放緩。</p><p>如果你有空閒的 30 分鐘，為什麼不嘗試下 Vue，看它可以給你提供什麼呢？</p>`,37)),t("p",null,[a[1]||(a[1]=s("P.S. — 這篇文檔很好的展示了 Vue 和其他框架的比較：",-1)),e(n,{href:"https://vuejs.org/v2/guide/comparison.html"},{default:p(()=>[...a[0]||(a[0]=[s("https://vuejs.org/v2/guide/comparison.html",-1)])]),_:1})]),a[16]||(a[16]=t("hr",null,null,-1)),t("p",null,[a[3]||(a[3]=s("via: ",-1)),e(n,{href:"https://medium.com/@dalaidunc/10-things-i-love-about-vue-505886ddaff2"},{default:p(()=>[...a[2]||(a[2]=[s("https://medium.com/@dalaidunc/10-things-i-love-about-vue-505886ddaff2",-1)])]),_:1})]),t("p",null,[a[7]||(a[7]=s("作者：",-1)),e(n,{href:"https://medium.com/@dalaidunc"},{default:p(()=>[...a[4]||(a[4]=[s("Duncan Grant",-1)])]),_:1}),a[8]||(a[8]=s(" 譯者：",-1)),e(n,{href:"https://github.com/yizhuoyan"},{default:p(()=>[...a[5]||(a[5]=[s("yizhuoyan",-1)])]),_:1}),a[9]||(a[9]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...a[6]||(a[6]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...a[11]||(a[11]=[s("Linux中國",-1)])]),_:1}),a[14]||(a[14]=s(" 榮譽推出",-1))])])}const T=l(d,[["render",h]]);export{v as __pageData,T as default};
